65	/// One build-time CUDA toolkit resolution covering the classic, conda, and
66	/// NVIDIA HPC SDK layouts; runtime loading (`LD_LIBRARY_PATH`, rpath) is out of scope.
67	pub struct CudaToolkit {
68	    pub root: PathBuf,
69	    /// `{root}/bin/nvcc` when present, otherwise bare `nvcc` from `$PATH`.
70	    pub nvcc: PathBuf,
71	    pub include_dirs: Vec<PathBuf>,
72	    lib_dirs: Vec<PathBuf>,
73	}
74	
75	impl CudaToolkit {
76	    pub fn discover() -> Self {
77	        println!("cargo:rerun-if-env-changed=CUDA_HOME");
78	        println!("cargo:rerun-if-env-changed=CUDA_PATH");
79	        let env_root = env::var("CUDA_HOME")
80	            .or_else(|_| env::var("CUDA_PATH"))
81	            .ok();
82	        if let Some(root) = env_root.as_deref().filter(|root| !Path::new(root).is_dir()) {
83	            println!(
84	                "cargo:warning=CUDA root {root} (from CUDA_HOME/CUDA_PATH) is not a directory"
85	            );
86	        }
87	        let root = env_root.map_or_else(|| PathBuf::from("/usr/local/cuda"), PathBuf::from);
88	        Self::from_root(root)
89	    }
90	
91	    fn from_root(root: PathBuf) -> Self {
92	        let nvcc = root.join("bin/nvcc");
93	        let nvcc = if nvcc.is_file() {
94	            nvcc
95	        } else {
96	            PathBuf::from("nvcc")
97	        };
98	
99	        let mut include_dirs = vec![root.join("include")];
100	        let mut lib_dirs = vec![root.join("lib64"), root.join("lib")];
101	        for target in target_dirs() {
102	            include_dirs.push(root.join(format!("targets/{target}/include")));
103	            lib_dirs.push(root.join(format!("targets/{target}/lib")));
104	        }
105	        // HPC SDK roots look like .../hpc_sdk/<os>/<release>/cuda/<ver>; the
106	        // math libraries live in the <release>/math_libs/<ver> sibling tree.
107	        if let (Some(version), Some(release)) =
108	            (root.file_name(), root.parent().and_then(Path::parent))
109	        {
110	            let math = release.join("math_libs").join(version);
111	            lib_dirs.push(math.join("lib64"));
112	            lib_dirs.push(math.join("lib"));
113	        }
114	
115	        Self {
116	            nvcc,
117	            include_dirs: existing_deduped(include_dirs),
118	            lib_dirs: existing_deduped(lib_dirs),
119	            root,
120	        }
121	    }
122	
123	    /// The include dir that actually contains `header` — host-compiler `-I`
124	    /// flags need this; on conda `include/` exists but lacks the CUDA headers.
125	    pub fn header_dir(&self, header: &str) -> Option<PathBuf> {
126	        self.include_dirs
127	            .iter()
128	            .find(|dir| dir.join(header).is_file())
129	            .cloned()
130	    }
131	
132	    pub fn link_search(&self) {
133	        if self.lib_dirs.is_empty() {
134	            println!(
135	                "cargo:warning=no CUDA library dir found under {}",
136	                self.root.display()
137	            );
138	        }
139	        for dir in &self.lib_dirs {
140	            println!("cargo:rustc-link-search=native={}", dir.display());
141	        }
142	    }
143	}
144	
145	fn existing_deduped(dirs: Vec<PathBuf>) -> Vec<PathBuf> {
146	    let mut seen = Vec::new();
147	    let mut out = Vec::new();
148	    for dir in dirs {
149	        if !dir.is_dir() {
150	            continue;
151	        }
152	        let canon = dir.canonicalize().unwrap_or_else(|_| dir.clone());
153	        if !seen.contains(&canon) {
154	            seen.push(canon);
155	            out.push(dir);
156	        }
157	    }
158	    out
159	}
